import fs from 'node:fs'; import os from 'node:os'; import path from 'node:path';
import {WorkflowStore} from './src/graph/store.ts';
import {Ticket,FileNode,ModuleNode,Artifact} from './src/graph/ontology.ts';
import {RuleStore} from './src/rules/store.ts';
import {indexCodebase} from './src/graph/indexer.ts';
import {closeAllTsLspClients} from './src/change/ts-lsp.ts';
import {resolveTicketGovernance,ruleAcceptanceFailures,readVerificationReceipt} from './src/ticket-operation-types.ts';
const root=fs.mkdtempSync(path.join(os.tmpdir(),'aiwf-prime-scope-'));
let store;
try {
 fs.mkdirSync(path.join(root,'src')); fs.mkdirSync(path.join(root,'tests'));
 fs.symlinkSync(path.resolve('node_modules'),path.join(root,'node_modules'));
 fs.writeFileSync(path.join(root,'.gitignore'),'node_modules\n.ai-workflow\n*.md\n');
 fs.writeFileSync(path.join(root,'src/add.ts'),'export function add(a:number,b:number){return a+b;}\n');
 fs.writeFileSync(path.join(root,'src/other.ts'),'export function other(){return 1;}\n');
 fs.writeFileSync(path.join(root,'tests/add.test.ts'),'import {test,expect} from "bun:test"; import {add} from "../src/add"; test("sum",()=>expect(add(2,3)).toBe(5));\n');
 fs.writeFileSync(path.join(root,'tsconfig.json'),JSON.stringify({compilerOptions:{target:'ESNext',module:'ESNext',moduleResolution:'bundler',types:['bun'],skipLibCheck:true}}));
 for(const args of [['init','-q'],['add','.'],['-c','user.name=Fixture','-c','user.email=fixture@example.invalid','commit','-qm','fixture']]){
  const p=Bun.spawnSync(['git',...args],{cwd:root,stderr:'pipe'});if(!p.success)throw Error(p.stderr.toString());
 }
 store=new WorkflowStore(root);await indexCodebase(store,root);
 const rs=new RuleStore(store);
 const owner=await store.upsertEntity(ModuleNode.dcr,{id:'OTHER',title:'Other module'});
 await store.relate(owner,'contains',(await store.getEntity('src/other.ts',FileNode.dcr)));
 const rule={id:'scope-rule',ruleId:'scope-rule',scope:{kind:'module',moduleId:'OTHER'},type:'coding',importance:10,rule:'other must return one.',status:'active',revision:1,provenance:'fixture',examples:[],references:[],test:{kind:'llm'}};
 await rs.saveRule(rule);
 const t=await store.upsertEntity(Ticket.dcr,{id:'T',title:'Keep addition direct',body:'Preserve signed addition.',lane:'Todo',acceptanceCriteria:['sum is correct']});
 await store.relate(t,'modifies',(await store.getEntity('src/add.ts',FileNode.dcr)));
 let suppliedRules;
 const opts={systemOne:{assess:async()=>null},critic:'none',maxRepairs:0,testCommands:[['bun','test','tests/add.test.ts']],
 implement:async()=>({changes:[{action:'replace_text',filePath:'src/other.ts',oldText:'return 1',newText:'return 2'}],testCommands:[]}),
 verify:async input=>{suppliedRules=input.dossier.governance.rules.map(r=>r.ruleId);return {criteria:[{criterion:'sum is correct',passed:true,evidence:'The actual addition test passed.'}],aspects:[],rules:[]};}};
 const result=await t.resolve(store,opts);
 const receipt=await store.getEntity('VERIFY-T',Artifact.dcr);
 await rs.saveRule({...rule,revision:2,rule:'other must remain at one; changes require independent evidence.'});
 const reuse=await t.resolve(store,{...opts,implement:async()=>{throw Error('Must re-review changed scope governance');},verify:async()=>{throw Error('Must independently reassess changed Rule');}});
 const after=await resolveTicketGovernance(store,t);
 const anchored=await store.upsertEntity(Ticket.dcr,{id:'TARGET',title:'Other target',body:'Keep other fixed.',acceptanceCriteria:['other returns one']});
 await store.relate(anchored,'modifies',(await store.getEntity('src/other.ts',FileNode.dcr)));
 const expected=await resolveTicketGovernance(store,anchored);
 const evidence={status:result.status,reuseAfterRuleChange:reuse.status,lane:(await store.getEntity('T',Ticket.dcr)).lane,changedFile:fs.readFileSync(path.join(root,'src/other.ts'),'utf8'),suppliedRules,afterRules:after.rules.map(r=>r.ruleId),rulesForActualChangedFile:expected.rules.map(r=>r.ruleId),receipt:receipt?readVerificationReceipt(receipt.body):null};
 console.log(JSON.stringify(evidence));
 const advisory={...expected,rules:expected.rules.map(r=>({...r,importance:6}))};
 const check={ruleId:'scope-rule',revision:1,fingerprint:expected.rules[0].fingerprint,verdict:'fail',evidence:'Expected rule violated.',evidenceIds:['src/other.ts'],limitations:[]};
 console.log(JSON.stringify({expectedRuleAssessmentFailures:ruleAcceptanceFailures(advisory,{criteria:[],aspects:[],rules:[check]},['src/other.ts'])}));
}finally{await closeAllTsLspClients();store?.close();fs.rmSync(root,{recursive:true,force:true});}
